    @Test
    void shutdownDrainsBlockedNativeAdmissionWithoutClosingItsEnvironments(
            @TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
        try (Fixture fixture = new Fixture(evidence)) {
            fixture.initialize();
            fixture.startForeignWriter();
            fixture.releaseScanAndAwaitNativeBegin();
            RetirementNativeTransaction ticket = fixture.gate.nativeOwner.get();
            assertNotNull(ticket, "the domain worker must register its real native writer owner");
            assertSame(ticket, fixture.backing.currentDeferredDomainNativeOwner());
            assertTrue(ticket.beginning(), "native begin must be in flight on the registered owner");
            assertNull(fixture.backing.getTripleStore().currentWriterTransaction(),
                    "shared TripleStore writer state is not bound before sink admission");
            AtomicReference<Thread> closer = new AtomicReference<>();
            Future<CloseOutcome> close = fixture.pool.submit(() -> {
                closer.set(Thread.currentThread());
                Throwable failure = null;
                try {
                    fixture.store.shutDown();
                } catch (Throwable problem) {
                    failure = problem;
                }
                return new CloseOutcome(failure, Thread.currentThread().isInterrupted());
            });
            awaitAnyStack(closer, "awaitPostReadyInitializationForShutdown", "acquireWriterLease");
            assertFalse(close.isDone(), "close must retain native owners while begin is in flight");
            assertSame(ticket, fixture.backing.currentDeferredDomainNativeOwner());
            assertTrue(ticket.beginning());
            assertTrue(new DirectoryLockManager(fixture.directory.toFile()).isLocked(),
                    "the directory remains excluded while the native owner is in flight");
            assertFalse(fixture.unsafeClose.get(), "neither environment may close during native admission");
            closer.get().interrupt();
            awaitAnyStack(closer, "awaitPostReadyInitializationForShutdown");
            assertFalse(close.isDone(), "interrupted shutdown must still join the in-flight native owner");
            assertFalse(fixture.gate.beginReturned.get(), "the foreign writer must still hold native admission");
            assertSame(ticket, fixture.backing.currentDeferredDomainNativeOwner());
            assertTrue(ticket.beginning());
            assertTrue(fixture.backing.getTripleStore().env != 0L,
                    "the statement environment must remain owned while begin is blocked");
            assertFalse(fixture.backing.valueStore().closedForDomainQualification(),
                    "the dictionary environment must remain owned while begin is blocked");
            assertTrue(new DirectoryLockManager(fixture.directory.toFile()).isLocked(),
                    "the directory must remain excluded until the native owner settles");
            assertFalse(fixture.unsafeClose.get());
            assertFalse(fixture.unsafeUnlock.get());
            fixture.releaseForeignWriter();
            CloseOutcome outcome = close.get(30, TimeUnit.SECONDS);
            assertAll("shutdown retains real owners and reports its interruption",
                    () -> assertTrue(outcome.interrupted(), "the close caller's interruption must be retained"),
                    () -> assertTrue(outcome.failure() == null || isExpectedCloseInterruption(outcome.failure()),
                            () -> "unexpected close failure: " + outcome.failure()),
                    () -> assertFalse(fixture.unsafeClose.get(), "native environments cannot close in flight"),
                    () -> assertFalse(fixture.unsafeUnlock.get(), "directory lock cannot be released in flight"));
        }
    }

