    private record CloseOutcome(Throwable failure, boolean interrupted) { }

    private static final class Gate {
        private final AtomicBoolean first = new AtomicBoolean(true);
        private final CountDownLatch scanned = new CountDownLatch(1);
        private final CountDownLatch releaseScan = new CountDownLatch(1);
        private final CountDownLatch beginCalled = new CountDownLatch(1);
        private final CountDownLatch beginReturnedLatch = new CountDownLatch(1);
        private final AtomicBoolean beginReturned = new AtomicBoolean();
        private final AtomicInteger nativeBeginsInFlight = new AtomicInteger();
        private final AtomicReference<Thread> worker = new AtomicReference<>();
        private final AtomicReference<RetirementNativeTransaction> nativeOwner = new AtomicReference<>();
    }

    private static LmdbStore instrumentedStore(Path directory, Gate gate, AtomicBoolean unsafeClose,
            AtomicBoolean unsafeUnlock) {
        return new LmdbStore(directory.toFile(), config()) {
            @Override
            protected void shutDownInternal() throws SailException {
                try {
                    super.shutDownInternal();
                } finally {
                    if (gate.nativeBeginsInFlight.get() != 0
                            && !new DirectoryLockManager(directory.toFile()).isLocked()) {
                        unsafeUnlock.set(true);
                    }
                }
            }

            @Override
            LmdbSailStore createBackingStore(File dataDir, StoreProperties properties, LmdbStoreConfig settings,
                    boolean estimatorEnabled) throws IOException, SailException {
                return new LmdbSailStore(dataDir, properties, settings, estimatorEnabled,
                        (valueDir, valueProperties, valueConfig) -> new ValueStore(valueDir, valueProperties, valueConfig) {
                            @Override
                            void closeEnvironment(long environment) {
                                assertSafeToClose(gate, unsafeClose);
                                super.closeEnvironment(environment);
                            }
                        },
                        (tripleDir, tripleProperties, tripleConfig, values) -> new TripleStore(tripleDir,
                                tripleProperties, tripleConfig, values, new TripleStore.EnvironmentLifecycle() {
                                    @Override public void afterOpen(long environment) { }
                                    @Override public void close(long environment) {
                                        assertSafeToClose(gate, unsafeClose);
                                        mdb_env_close(environment);
                                    }
                                }) {
                            @Override
                            DeferredRdfTermDomainPlan scanDeferredRdfTermDomains(TxnManager.Txn triples,
                                    ValueStore.ReadSnapshot snapshot) throws IOException {
                                DeferredRdfTermDomainPlan plan = super.scanDeferredRdfTermDomains(triples, snapshot);
                                if (gate.first.compareAndSet(true, false)) {
                                    gate.worker.set(Thread.currentThread());
                                    gate.scanned.countDown();
                                    try {
                                        if (!gate.releaseScan.await(30, TimeUnit.SECONDS)) {
                                            throw new IOException("test did not release completed domain scan");
                                        }
                                    } catch (InterruptedException interrupted) {
                                        Thread.currentThread().interrupt();
                                        throw new IOException("domain scan gate interrupted", interrupted);
                                    }
                                }
                                return plan;
                            }

                            @Override
                            void beginDeferredDomainNativeWriter(RetirementNativeTransaction nativeOwner)
                                    throws IOException {
                                boolean domain = Thread.currentThread() == gate.worker.get();
                                if (domain) {
                                    gate.nativeOwner.set(nativeOwner);
                                    gate.nativeBeginsInFlight.incrementAndGet();
                                    gate.beginCalled.countDown();
                                }
                                try {
                                    super.beginDeferredDomainNativeWriter(nativeOwner);
                                } finally {
                                    if (domain) {
                                        gate.nativeBeginsInFlight.decrementAndGet();
                                        gate.beginReturned.set(true);
                                        gate.beginReturnedLatch.countDown();
                                    }
                                }
                            }
                        });
            }
        };
    }

    private static void assertSafeToClose(Gate gate, AtomicBoolean unsafeClose) {
        if (gate.nativeBeginsInFlight.get() != 0) {
            unsafeClose.set(true);
            throw new AssertionError("native begin is in flight; environment must be retained");
        }
    }

    private static boolean isExpectedCloseInterruption(Throwable failure) {
        for (Throwable cause = failure; cause != null; cause = cause.getCause()) {
            if (cause instanceof InterruptedException || cause instanceof InterruptedSailException
                    || cause instanceof SailException
                            && "LMDB store is closed or shutting down".equals(cause.getMessage())) {
                return true;
            }
        }
        return false;
    }

    private static void awaitAnyStack(AtomicReference<Thread> owner, String... methods) {
        long until = System.nanoTime() + TimeUnit.SECONDS.toNanos(20);
        while (System.nanoTime() < until) {
            Thread thread = owner.get();
            if (thread != null) {
                for (StackTraceElement frame : thread.getStackTrace()) {
                    for (String method : methods) {
                        if (frame.getMethodName().contains(method)) return;
                    }
                }
                if (!thread.isAlive()) throw new AssertionError("owner exited before its close drain");
            }
            Thread.yield();
        }
        Thread thread = owner.get();
        throw new AssertionError("owner did not reach an expected close drain: "
                + (thread == null ? "missing thread" : Arrays.toString(thread.getStackTrace())));
    }

    private static void awaitStack(AtomicReference<Thread> owner, String method) {
        long until = System.nanoTime() + TimeUnit.SECONDS.toNanos(20);
        while (System.nanoTime() < until) {
            Thread thread = owner.get();
            if (thread != null) {
                for (StackTraceElement frame : thread.getStackTrace()) {
                    if (frame.getMethodName().contains(method)) return;
                }
                if (!thread.isAlive()) throw new AssertionError("owner exited before " + method);
            }
            Thread.yield();
        }
        Thread thread = owner.get();
        throw new AssertionError("owner did not reach " + method + ": "
                + (thread == null ? "missing thread" : Arrays.toString(thread.getStackTrace())));
    }

    private static void seed(Path directory) throws Exception {
        LmdbStore store = new LmdbStore(directory.toFile(), config());
        try {
            store.init();
            LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
            try (var connection = store.getConnection()) {
                connection.begin();
                connection.addStatement(S, P, O);
                connection.commit();
            }
        } finally {
            store.shutDown();
        }
        StoreProperties properties = new StoreProperties(directory.toFile());
        assertTrue(properties.load());
        properties.setRdfTermDomainsVersion("test-obsolete-domain-profile");
        properties.save();
    }

    private static LmdbStoreConfig config() {
        return new LmdbStoreConfig("spoc,posc").setInlineLiterals(false).setSketchEstimatorEnabled(false)
                .setFrontierEstimatorMode(FrontierEstimatorMode.OFF).setPredicateGuaranteeIndexEnabled(true)
                .setPredicateGuaranteeIndexAutoRebuild(true).setForceSync(true);
    }

    public static final class ForeignWriter {
        public static void main(String[] args) throws Exception {
            try (MemoryStack stack = MemoryStack.stackPush()) {
                PointerBuffer handle = stack.mallocPointer(1);
                if (mdb_env_create(handle) != MDB_SUCCESS) throw new IOException("env create failed");
                long env = handle.get(0);
                try {
                    if (mdb_env_set_maxdbs(env, 100) != MDB_SUCCESS) throw new IOException("maxdbs failed");
                    if (mdb_env_open(env, args[0], MDB_NOTLS, 0664) != MDB_SUCCESS) throw new IOException("open failed");
                    PointerBuffer writer = stack.mallocPointer(1);
                    if (mdb_txn_begin(env, 0L, 0, writer) != MDB_SUCCESS) throw new IOException("begin failed");
                    long txn = writer.get(0);
                    try {
                        System.out.println("FOREIGN_TRIPLE_WRITER_HELD");
                        System.out.flush();
                        System.in.read();
                    } finally {
                        mdb_txn_abort(txn);
                    }
                } finally {
                    mdb_env_close(env);
                }
            }
        }
    }
